-- Read-only per-team calendar/context inventory; age_group may not yet exist.
begin read only; select t.id as team_id,count(distinct m.id)::int matches,count(distinct m.id) filter(where m.federation_start_at>now())::int future,count(distinct m.id) filter(where m.home_score is not null and m.away_score is not null)::int results,count(distinct m.id) filter(where m.raw_data->>'report_status'='verified')::int verified_reports,count(distinct b.pilot_match_id)::int basic_contexts,count(distinct src.match_id)::int linked_source_contexts,to_jsonb(t)->>'age_group' actual_age_group from public.teams t join public.seasons se on se.id=t.season_id left join public.federation_team_entries e on e.club_team_id=t.id left join public.federation_match_teams mt on mt.entry_id=e.id left join public.federation_matches m on m.id=mt.match_id left join public.basic_match_contexts b on b.catalogue_match_id=m.id and not b.practice left join public.federation_match_sources src on src.official_data->>'calendar_match_id'=m.id::text where t.club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd' and se.label='2026/27' group by t.id order by t.id; rollback;
